/// Helix Drill. Cost 0, single-target Attack. Deal `base` damage `N`
/// times, where `N` = total energy spent this turn minus Helix's own
/// effective cost (it is in the Play pile when its `CalculatedHits`
/// resolves). Mirrors C# `HelixDrill` (HelixDrill.cs:20-43, 51-58):
/// `CalculatedHits = sum(EnergySpentEntry this turn) - (Pile==Play ?
/// EnergyCost : 0)`, dealt via `DamageCmd.Attack(base).WithHitCount(N)
/// .Targeting(Target)`. `energy_spent_this_turn` already includes this
/// Helix play (the tally is bumped in `play_card` before `OnPlay`), so
/// subtracting its own cost yields the energy spent on prior cards.
/// `CalculatedHits`: Energy spent this turn, excluding what this card itself
/// costs. Shared with the card face — see `crate::cards::preview`.
///
/// On the face the card has not been paid for yet, so its own cost is not in
/// `energy_spent_this_turn` and subtracting it would under-count by one play.
/// The subtraction is therefore keyed to whether THIS card is the one
/// resolving, which is exactly when the energy has already been spent.
pub(crate) fn preview_helix_drill(
    state: &CombatState,
    card: &Card,
    _target: Option<CreatureUid>,
) -> i32 {
    let own_cost = if sts2_core::card_effects::resolving_card_uid(state) == Some(card.uid) {
        if state.game_version >= sts2_core::GameVersion::V0_113_0 {
            // v0.113.0 `HelixDrill.cs:36-39`: subtract the in-progress
            // play's `Resources.EnergySpent`, not the card's current cost.
            // `CardCmd.AutoPlay` sets it to 0 (CardCmd.cs:125); Rust's
            // `energy_spent` then holds the play's `EnergyValue` instead.
            if state.combat_log.resolving_auto_play {
                0
            } else {
                card.energy_spent
            }
        } else {
            sts2_core::hooks::effective_card_cost(state, card.uid)
        }
    } else {
        0
    };
    (state.combat_log.energy_spent_this_turn - own_cost).max(0)
}

pub(crate) fn play_helix_drill(
    state: &mut CombatState,
    target: Option<CreatureUid>,
) -> EffectResult {
    let t = target.expect("HelixDrill: Enemy-targeted");
    let base = current_card_damage(state);
    let hits = resolving_preview(state, preview_helix_drill, target);
    for _ in 0..hits {
        let _ = deal_damage_player_to_enemy(state, t, base);
    }
    EffectResult::Resolved
}

